import os

import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("orders")

EMAIL_API_URL = "https://api.emailprovider.example.com/v1/send"


@mcp.tool()
def send_shipping_confirmation_email(order_id: str, customer_email: str, carrier_name: str, tracking_number: str) -> dict:
    email_subject_line = f"Your order {order_id} has shipped"
    email_body_text_content = (
        f"Good news! Order {order_id} is on its way with {carrier_name}.\n"
        f"Tracking number: {tracking_number}"
    )
    email_provider_request_payload = {
        "to": customer_email,
        "from": "orders@shop.example.com",
        "subject": email_subject_line,
        "text": email_body_text_content,
    }
    email_provider_authorization_headers = {
        "Authorization": "Bearer " + os.environ["EMAIL_API_KEY"]
    }
    email_provider_http_response = requests.post(
        EMAIL_API_URL,
        json=email_provider_request_payload,
        headers=email_provider_authorization_headers,
        timeout=15,
    )
    email_provider_http_response.raise_for_status()
    return {
        "order_id": order_id,
        "sent_to": customer_email,
        "status_code": email_provider_http_response.status_code,
    }

import sqlite3
from contextlib import closing

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("orders")

DB_PATH = "/var/data/store.db"


@mcp.tool()
def issue_store_credit_to_customer(customer_id: str, order_id: str, amount_cents: int, reason: str) -> dict:
    if amount_cents <= 0:
        raise ValueError("amount_cents must be positive")
    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            conn.execute(
                "INSERT INTO credit_ledger (customer_id, order_id, amount_cents, reason) VALUES (?, ?, ?, ?)",
                (customer_id, order_id, amount_cents, reason),
            )
            conn.execute(
                "UPDATE customers SET credit_balance_cents = credit_balance_cents + ? WHERE id = ?",
                (amount_cents, customer_id),
            )
            row = conn.execute(
                "SELECT credit_balance_cents FROM customers WHERE id = ?",
                (customer_id,),
            ).fetchone()
    if row is None:
        raise LookupError(f"customer {customer_id} not found")
    return {"customer_id": customer_id, "new_balance_cents": row[0]}
